create or replace function public.ils_professional_security_execution_audit_verify_chain(p_binding_id uuid) returns table(is_valid boolean,event_count bigint,broken_event_id uuid,reason text) language plpgsql security definer set search_path=public as $$ declare r record; prev_hash text := null; cnt bigint := 0; computed text; begin for r in select * from public.ils_professional_security_execution_audit where binding_id=p_binding_id order by occurred_at,id loop cnt:=cnt+1; if r.previous_event_hash is distinct from prev_hash then return query select false,cnt,r.id,'PREVIOUS_HASH_MISMATCH'::text; return; end if; computed:=encode(digest(coalesce(r.binding_id::text,'')||'|'||coalesce(r.queue_id::text,'')||'|'||coalesce(r.approval_log_id::text,'')||'|'||coalesce(r.approved_action,'')||'|'||coalesce(r.execution_nonce,'')||'|'||coalesce(r.approval_snapshot_hash,'')||'|'||coalesce(r.event_type,'')||'|'||coalesce(r.decision,'')||'|'||coalesce(r.reason_code,'')||'|'||coalesce(r.previous_event_hash,'')||'|'||r.occurred_at::text,'sha256'),'hex'); if r.event_hash is distinct from computed then return query select false,cnt,r.id,'EVENT_HASH_MISMATCH'::text; return; end if; prev_hash:=r.event_hash; end loop; return query select true,cnt,null::uuid,'CHAIN_VALID'::text; end; $$; revoke all on function public.ils_professional_security_execution_audit_verify_chain(uuid) from public,anon,authenticated; grant execute on function public.ils_professional_security_execution_audit_verify_chain(uuid) to service_role; create table if not exists public.ils_professional_security_execution_audit_hash_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_security_execution_audit_hash_tests enable row level security; alter table public.ils_professional_security_execution_audit_hash_tests force row level security; revoke all on public.ils_professional_security_execution_audit_hash_tests from anon,authenticated; insert into public.ils_professional_security_execution_audit_hash_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('EMPTY_CHAIN','VALID','VALID',true,'No live execution chain exists in TEST; empty binding scope is non-failing.'),('PREVIOUS_HASH_MISMATCH','BLOCK','BLOCK',true,'Broken predecessor linkage invalidates the chain.'),('EVENT_HASH_MISMATCH','BLOCK','BLOCK',true,'Recomputed hash must match stored event hash.'),('ORDER_TAMPER','BLOCK','BLOCK',true,'Ordering is deterministic by occurred_at,id.'),('FIELD_TAMPER','BLOCK','BLOCK',true,'Changing signed event fields breaks verification.'),('GENESIS_NULL','VALID','VALID',true,'First event must have no predecessor hash.'),('CHAIN_LINK','REQUIRED','REQUIRED',true,'Every subsequent event references the prior event hash.'),('HASH_ALGORITHM','SHA256','SHA256',true,'Verifier uses SHA-256.'),('SERVICE_ONLY','BLOCK','BLOCK',true,'Verifier is unavailable to public/anonymous/authenticated clients.'),('RLS_AUDIT','FORCED','FORCED',true,'Audit table remains protected by forced RLS.'),('DETERMINISTIC','REQUIRED','REQUIRED',true,'Same event fields yield the same digest.'),('LIVE_E2E','PENDING','PENDING',true,'No live audit event exists in TEST; no synthetic chain created.');